const pm = require('picomatch');
const norm = p => p.replace(/\\\\/g,'/').replace(/^\.\//,'');
function matcherFor(pattern){
  const p = norm(pattern);
  const patterns = /[*?[\]{}!]/.test(p) ? [p] : [p, p+'/**', '**/'+p, '**/'+p+'/**'];
  console.log('pattern', JSON.stringify(pattern), '=> expansions', JSON.stringify(patterns));
  return pm(patterns, {dot:true});
}
for (const pat of ['secrets/','secrets']) {
  const m = matcherFor(pat);
  for (const path of ['secrets','secrets/key.pem','secrets/deep/a/b.txt','src/secrets/key.pem','docs/secrets']) {
    console.log('   ', JSON.stringify(path), '->', m(path));
  }
}
"

